// Your shop's public address and how prices read.
const STORE_URL = 'https://your-store.com';
const PRICE = (amount) => `From $${amount}`;

// Builds the caption and the photos from the Shopify product.
const product = $json;
const description = (product.body_html || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/ ([.,!?;:])/g, '$1')
  .trim();
const short = description.length > 220 ? description.slice(0, 220).replace(/\s+\S*$/, '') + '...' : description;
const prices = (product.variants || []).map((v) => Number(v.price)).filter((n) => !Number.isNaN(n));
const price = prices.length ? PRICE(Math.min(...prices).toFixed(2)) : '';
// Up to 4 photos: more than one makes a carousel.
const photos = (product.images || []).map((image) => image.src).filter(Boolean).slice(0, 4);
return {
  json: {
    text: [`New in: ${product.title}`, short, price, `${STORE_URL}/products/${product.handle}`].filter(Boolean).join('\n\n'),
    photos: photos.join(','),
  },
};
